package com.xplayer.lite;
import android.content.*;
import android.net.Uri;
import androidx.test.core.app.ActivityScenario;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;
import java.io.*;
import java.util.concurrent.atomic.AtomicBoolean;
@RunWith(AndroidJUnit4.class)
public class AdvancedTest{
 private Context app(){return InstrumentationRegistry.getInstrumentation().getTargetContext();}
 private File sample(String name)throws Exception{File f=new File(app().getCacheDir(),"advanced-"+name);try(InputStream in=InstrumentationRegistry.getInstrumentation().getContext().getAssets().open(name);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return f;}
 @Test public void playlistAndBackup()throws Exception{Context c=app();String n="test-playlist";ProPrefs.deletePlaylist(c,n);Uri u=Uri.parse("content://media/external/video/media/99999");assertTrue(ProPrefs.createPlaylist(c,n));assertTrue(ProPrefs.playlistAdd(c,n,u));assertTrue(ProPrefs.list(c,ProPrefs.playlistKey(n)).contains(u.toString()));ProPrefs.playlistRemove(c,n,u);assertTrue(ProPrefs.list(c,ProPrefs.playlistKey(n)).isEmpty());ProPrefs.deletePlaylist(c,n);ProPrefs.get(c).edit().putInt("accent",2).commit();String backup=Backup.exportJson(c);ProPrefs.get(c).edit().putInt("accent",0).commit();Backup.restore(c,backup);assertEquals(2,ProPrefs.number(c,"accent",0));ProPrefs.get(c).edit().remove("accent").commit();}
 @Test public void vlcSoftwarePlayback()throws Exception{File f=sample("sample.mp4");try(ActivityScenario<VlcActivity> s=ActivityScenario.launch(new Intent(app(),VlcActivity.class).setData(Uri.fromFile(f)).putExtra("software",true))){AtomicBoolean playing=new AtomicBoolean();long deadline=android.os.SystemClock.elapsedRealtime()+25000;while(android.os.SystemClock.elapsedRealtime()<deadline){s.onActivity(a->playing.set(a.player!=null&&!a.failed&&a.player.isPlaying()&&a.player.getTime()>300));if(playing.get())break;Thread.sleep(150);}assertTrue("LibVLC SW playback must advance",playing.get());android.util.Log.i("XPlayerTest","PASS LibVLC software playback");}finally{f.delete();}}
 @Test public void mp3Export()throws Exception{File input=sample("sample.mp4"),output=new File(app().getCacheDir(),"advanced-result.mp3");try{ExportActivity.encodeMp3(input,output);assertTrue(output.length()>1000);android.media.MediaExtractor e=new android.media.MediaExtractor();try{e.setDataSource(output.getAbsolutePath());assertTrue(e.getTrackCount()>0);assertEquals("audio/mpeg",e.getTrackFormat(0).getString(android.media.MediaFormat.KEY_MIME));}finally{e.release();}android.util.Log.i("XPlayerTest","PASS MP3 export with MPEG audio track");}finally{input.delete();output.delete();}}
 @Test public void backgroundPlayback()throws Exception{File input=sample("sample.mp3");Context c=app();try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){scenario.onActivity(activity->activity.startService(new Intent(activity,BackgroundService.class).setAction("xplayer.BACKGROUND").setData(Uri.fromFile(input)).putExtra("title","Background test")));scenario.moveToState(androidx.lifecycle.Lifecycle.State.CREATED);AtomicBoolean playing=new AtomicBoolean();long deadline=android.os.SystemClock.elapsedRealtime()+20000;while(android.os.SystemClock.elapsedRealtime()<deadline){InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{androidx.media3.exoplayer.ExoPlayer p=BackgroundService.active;playing.set(p!=null&&p.isPlaying()&&p.getCurrentPosition()>300);});if(playing.get())break;Thread.sleep(150);}assertTrue("Background player must keep playing without foreground activity",playing.get());android.util.Log.i("XPlayerTest","PASS background media session playback");}finally{InstrumentationRegistry.getInstrumentation().runOnMainSync(()->c.stopService(new Intent(c,BackgroundService.class)));input.delete();}}
 @Test public void trimMp4()throws Exception{File input=sample("sample.mp4"),out=new File(app().getCacheDir(),"advanced-trim.mp4");out.delete();java.util.concurrent.CountDownLatch latch=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicReference<Throwable> err=new java.util.concurrent.atomic.AtomicReference<>();java.util.concurrent.atomic.AtomicReference<androidx.media3.transformer.Transformer> transformer=new java.util.concurrent.atomic.AtomicReference<>();try{InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{try{androidx.media3.transformer.Transformer t=new androidx.media3.transformer.Transformer.Builder(app()).addListener(new androidx.media3.transformer.Transformer.Listener(){public void onCompleted(androidx.media3.transformer.Composition c,androidx.media3.transformer.ExportResult r){latch.countDown();}public void onError(androidx.media3.transformer.Composition c,androidx.media3.transformer.ExportResult r,androidx.media3.transformer.ExportException e){err.set(e);latch.countDown();}}).build();transformer.set(t);androidx.media3.common.MediaItem m=new androidx.media3.common.MediaItem.Builder().setUri(Uri.fromFile(input)).setClippingConfiguration(new androidx.media3.common.MediaItem.ClippingConfiguration.Builder().setStartPositionMs(1000).setEndPositionMs(4000).build()).build();t.start(new androidx.media3.transformer.EditedMediaItem.Builder(m).build(),out.getAbsolutePath());}catch(Throwable t){err.set(t);latch.countDown();}});assertTrue("Export completion timed out",latch.await(90,java.util.concurrent.TimeUnit.SECONDS));if(err.get()!=null)throw new AssertionError("Trim failed",err.get());assertTrue(out.length()>1000);android.media.MediaMetadataRetriever r=new android.media.MediaMetadataRetriever();try{r.setDataSource(out.getAbsolutePath());long duration=Long.parseLong(r.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION));assertTrue("Unexpected trimmed duration: "+duration,duration>=2400&&duration<=3700);assertEquals("yes",r.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_HAS_VIDEO));}finally{r.release();}android.util.Log.i("XPlayerTest","PASS trimmed MP4 duration and video track");}finally{InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{if(transformer.get()!=null)transformer.get().cancel();});input.delete();out.delete();}}
 @Test public void recognizesUnindexedMedia(){assertEquals(1,TreeScanner.kind("Movie.RMVB","application/octet-stream"));assertEquals(2,TreeScanner.kind("music.FLAC",null));assertEquals(0,TreeScanner.kind("random.pdf","application/pdf"));assertTrue(TreeScanner.subtitle("Movie.SRT"));assertEquals(TreeScanner.stem("movie.MKV"),TreeScanner.stem("Movie.srt"));}
 @Test public void automaticBackgroundOnLeave()throws Exception{File input=sample("sample.mp3");Context c=app();ProPrefs.get(c).edit().putInt("background_mode",3).putBoolean("compat_notification",true).putBoolean("show_media_notification",true).commit();try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(new Intent(c,MainActivity.class).setAction(Intent.ACTION_VIEW).setData(Uri.fromFile(input)))){AtomicBoolean ready=new AtomicBoolean();long until=android.os.SystemClock.elapsedRealtime()+15000;while(android.os.SystemClock.elapsedRealtime()<until){scenario.onActivity(a->ready.set(a.player!=null&&a.player.isPlaying()));if(ready.get())break;Thread.sleep(150);}assertTrue("foreground playback",ready.get());scenario.onActivity(a->a.onUserLeaveHint());scenario.moveToState(androidx.lifecycle.Lifecycle.State.CREATED);AtomicBoolean playing=new AtomicBoolean();until=android.os.SystemClock.elapsedRealtime()+15000;while(android.os.SystemClock.elapsedRealtime()<until){InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{androidx.media3.exoplayer.ExoPlayer p=BackgroundService.active;playing.set(p!=null&&p.isPlaying()&&p.getCurrentPosition()>300);});if(playing.get())break;Thread.sleep(150);}assertTrue("Automatic handoff should keep playing in service",playing.get());android.app.NotificationManager nm=(android.app.NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);android.app.PendingIntent pause=null;until=android.os.SystemClock.elapsedRealtime()+5000;while(android.os.SystemClock.elapsedRealtime()<until){for(android.service.notification.StatusBarNotification n:nm.getActiveNotifications())if(n.getId()==BackgroundService.BACKGROUND_COMPAT_ID&&n.getNotification().actions!=null)for(android.app.Notification.Action action:n.getNotification().actions)if("Pause".contentEquals(action.title))pause=action.actionIntent;if(pause!=null)break;Thread.sleep(100);}assertNotNull("Background alternative notification must provide pause",pause);pause.send();Thread.sleep(500);InstrumentationRegistry.getInstrumentation().runOnMainSync(()->assertTrue(BackgroundService.active!=null&&!BackgroundService.active.isPlaying()));}finally{InstrumentationRegistry.getInstrumentation().runOnMainSync(()->c.stopService(new Intent(c,BackgroundService.class)));ProPrefs.get(c).edit().remove("background_mode").remove("compat_notification").remove("show_media_notification").commit();input.delete();}}
}
